    </div>''')

# prices
rep('''<span class="amt" data-m="12" data-y="10">$10</span>''','<span class="amt" data-plan="pro">$10</span>')
rep('''<div class="billed" data-m="Billed monthly" data-y="Billed $120 yearly">Billed $120 yearly</div>''','<div class="billed" data-plan="pro"></div>')
rep('''<span class="amt" data-m="29" data-y="24">$24</span>''','<span class="amt" data-plan="studio">$24</span>')
rep('''<div class="billed" data-m="Billed monthly" data-y="Billed $288 yearly">Billed $288 yearly</div>''','<div class="billed" data-plan="studio"></div>')
rep('Prices in USD. Local taxes may apply.','Local taxes may apply.')

# enterprise
rep('''    <p class="fine">''','''    <div class="enterprise reveal">
      <div><h2>Agency or larger team?</h2><p>Unlimited seats, SSO, custom contracts and a dedicated account manager.</p></div>
      <a class="btn" href="#">Contact sales</a>
    </div>
    <p class="fine">''')

# reveal on sections
s=s.replace('<section id="compare">','<section id="compare" class="reveal">').replace('<section>\n      <div class="quote">','<section class="reveal">\n      <div class="quote">').replace('<section id="faq">','<section id="faq" class="reveal">')

# JS
i=s.index('<script>'); j=s.index('</script>')+9
