  // Fixed prices per currency: [monthly, per-month-when-yearly]
  const PRICES = {
    USD:{sym:'$',pro:[12,10],studio:[29,24]},
    EUR:{sym:'€',pro:[11,9],studio:[27,22]},
    GBP:{sym:'£',pro:[10,8],studio:[24,20]}
  };
  const state = {period:'yearly', cur:'USD'};
  const btns = {monthly: document.getElementById('monthly'), yearly: document.getElementById('yearly')};
  const sel = document.getElementById('cur');

  function render(){
    const {period, cur} = state, c = PRICES[cur], y = period === 'yearly';
    for (const [k,b] of Object.entries(btns)) b.setAttribute('aria-pressed', k === period);
    document.querySelectorAll('[data-plan]').forEach(el=>{
      const [m, yr] = c[el.dataset.plan];
      if (el.classList.contains('amt')) { el.textContent = c.sym + (y ? yr : m); return; }
      if (y) {
        const save = (m - yr) * 12;
        el.innerHTML = `Billed ${c.sym}${yr*12} yearly · <span class="saving">save ${c.sym}${save}</span>`;
      } else el.textContent = 'Billed monthly';
    });
  }
  btns.monthly.onclick = () => { state.period = 'monthly'; render(); };
  btns.yearly.onclick = () => { state.period = 'yearly'; render(); };
  sel.onchange = () => { state.cur = sel.value; render(); };

  // Guess currency from locale
  try {
    const r = (navigator.language || '').toUpperCase();
    if (/-GB$/.test(r)) state.cur = 'GBP';
    else if (/-(DE|FR|ES|IT|NL|IE|PT|AT|BE|FI)$/.test(r)) state.cur = 'EUR';
    sel.value = state.cur;
  } catch(e){}
  render();

  // Scroll reveal (content stays visible if JS/IO unavailable)
  const rv = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } }), {threshold:.1});
    rv.forEach(el => io.observe(el));
  } else rv.forEach(el => el.classList.add('in'));
</script>'''+s[j:]
open(p,'w').write(s)
EOF
